  let L = loadClamped(velocityTex, x - 1, y).y;
  let R = loadClamped(velocityTex, x + 1, y).y;
  let T = loadClamped(velocityTex, x, y - 1).x;
  let B = loadClamped(velocityTex, x, y + 1).x;
  let vorticity = (R - L - T + B) * 0.5;

